SELECT cliente_id, nombre, saldo_abierto, saldo_vencido, max_dias_vencido
FROM centinela.v_cartera_cliente
WHERE cliente_id = :cliente_id;

SELECT coalesce(sum(pesos_en_riesgo), 0) AS dinero_en_riesgo
FROM alertas
WHERE estado = 'propuesta';

SELECT count(*) AS decisiones_pendientes
FROM alertas
WHERE estado = 'propuesta';

SELECT coalesce(sum(recuperable_mes), 0) AS recuperable_mes
FROM alertas
WHERE estado = 'propuesta';
